CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash TEXT NOT NULL, role VARCHAR(30) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE patients (id UUID PRIMARY KEY REFERENCES users(id), preferred_language VARCHAR(10) NOT NULL DEFAULT 'en', region VARCHAR(120), deleted_at TIMESTAMPTZ);
CREATE TABLE caregiver_patient_assignments (caregiver_id UUID REFERENCES users(id), patient_id UUID REFERENCES patients(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (caregiver_id, patient_id));
CREATE TABLE games (game_type VARCHAR(50) PRIMARY KEY, display_name VARCHAR(120) NOT NULL);
CREATE TABLE game_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), patient_id UUID NOT NULL REFERENCES patients(id), game_type VARCHAR(50) NOT NULL REFERENCES games(game_type), difficulty_level INTEGER NOT NULL, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE INDEX game_sessions_patient_time_idx ON game_sessions(patient_id, started_at);
CREATE TABLE game_results (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), session_id UUID NOT NULL UNIQUE REFERENCES game_sessions(id), event_id UUID NOT NULL UNIQUE, score INTEGER NOT NULL, accuracy DOUBLE PRECISION NOT NULL, response_time DOUBLE PRECISION NOT NULL, attempts INTEGER NOT NULL, mistakes INTEGER NOT NULL DEFAULT 0, completed BOOLEAN NOT NULL, cps DOUBLE PRECISION, accuracy_component DOUBLE PRECISION, reaction_component DOUBLE PRECISION, completion_component DOUBLE PRECISION, consistency_component DOUBLE PRECISION, recommended_difficulty INTEGER, recommended_activity VARCHAR(50), recommendation_model VARCHAR(40), recommendation_explanation TEXT, caregiver_notification BOOLEAN NOT NULL DEFAULT FALSE, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX game_results_event_idx ON game_results(event_id);
CREATE INDEX game_results_recorded_idx ON game_results(recorded_at);
CREATE TABLE reminders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), patient_id UUID NOT NULL REFERENCES patients(id), title VARCHAR(120) NOT NULL, description TEXT, reminder_type VARCHAR(40) NOT NULL, reminder_time VARCHAR(5) NOT NULL, recurrence VARCHAR(20) NOT NULL DEFAULT 'DAILY', start_date DATE NOT NULL DEFAULT CURRENT_DATE, end_date DATE, enabled BOOLEAN NOT NULL DEFAULT TRUE, completed_at TIMESTAMPTZ);
CREATE INDEX reminders_patient_time_idx ON reminders(patient_id, reminder_time);
CREATE TABLE alerts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), patient_id UUID NOT NULL REFERENCES patients(id), message TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'new', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX alerts_patient_status_idx ON alerts(patient_id, status);
CREATE TABLE daily_aggregates (patient_id UUID REFERENCES patients(id), stat_date DATE NOT NULL, sessions_completed INTEGER NOT NULL DEFAULT 0, games_played INTEGER NOT NULL DEFAULT 0, average_score DOUBLE PRECISION NOT NULL DEFAULT 0, average_accuracy DOUBLE PRECISION NOT NULL DEFAULT 0, average_reaction_time DOUBLE PRECISION NOT NULL DEFAULT 0, completion_rate DOUBLE PRECISION NOT NULL DEFAULT 0, PRIMARY KEY (patient_id, stat_date));
CREATE TABLE weekly_aggregates (patient_id UUID REFERENCES patients(id), week_start DATE NOT NULL, games_played INTEGER NOT NULL DEFAULT 0, average_score DOUBLE PRECISION NOT NULL DEFAULT 0, average_accuracy DOUBLE PRECISION NOT NULL DEFAULT 0, average_reaction_time DOUBLE PRECISION NOT NULL DEFAULT 0, PRIMARY KEY (patient_id, week_start));
CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id), action VARCHAR(120) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
